(function(){'use strict';var fmt=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});function init(){document.querySelectorAll('.bmd-n8n-cost').forEach(function(root){var months=12;var keys=['eur','fx','vps','renew','intro','hours','hourly','backup','monitor','setup'];function get(k){var x=root.querySelector('[data-n8n="'+k+'"]');var n=x?Number(x.value):0;return Number.isFinite(n)?Math.max(0,n):0;}function o(k,v){var x=root.querySelector('[data-out="'+k+'"]');if(x)x.textContent=v;}function update(){var euro=get('eur'),exchange=get('fx'),start=get('vps'),renew=get('renew'),promoMonths=Math.floor(get('intro')),hours=get('hours'),hourly=get('hourly'),backup=get('backup'),monitor=get('monitor'),setup=get('setup');var cloud=months*euro*exchange;var vpsServer=Math.min(months,promoMonths)*start+Math.max(0,months-promoMonths)*renew;var work=months*hours*hourly;var vps=vpsServer+work+months*(backup+monitor)+setup;var max=Math.max(cloud,vps,1);o('cloud',fmt.format(cloud));o('vps',fmt.format(vps));o('difference',(vps>=cloud?'A VPS custa ':'O Cloud custa ')+fmt.format(Math.abs(vps-cloud))+' '+(vps>=cloud?'a mais':'a mais')+' nesse período.');o('work',fmt.format(work));o('server',fmt.format(vpsServer));o('cloudyear',fmt.format(cloud/months));o('vpsyear',fmt.format(vps/months));var c=root.querySelector('.bmd-n8n-bar.cloud span'),v=root.querySelector('.bmd-n8n-bar.vps span');if(c)c.style.width=(100*cloud/max).toFixed(2)+'%';if(v)v.style.width=(100*vps/max).toFixed(2)+'%';var p=root.querySelector('[data-months-label]');if(p)p.textContent=months+' meses';}root.querySelectorAll('[data-n8n]').forEach(function(x){x.addEventListener('input',update)});root.querySelectorAll('[data-months]').forEach(function(b){b.addEventListener('click',function(){months=Number(b.getAttribute('data-months'));root.querySelectorAll('[data-months]').forEach(function(z){z.setAttribute('aria-pressed',z===b?'true':'false')});update()})});update()})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();